1	/* Ateliê Bruma | tokens (marca FICTÍCIA) | UI-001 APROVADO em 2026-10-22 (ver handoffs/approval-log.md)
2	   Mantido à mão em sincronia com tokens.json. Sem identidade da EIXO.
3	   Contrastes: calculados à mão e conferidos por script pela revisão independente (evidence/UI-001/contrast-check.json); ver ui-handoff.md §7.
4	   Fontes: não carregadas aqui. Fraunces e Figtree (SIL OFL 1.1) devem ser auto-hospedadas pelo Developer. */
5	
6	:root {
7	  /* ---------- Primitives de cor ---------- */
8	  --fog-50:    #F4F1EC;
9	  --fog-100:   #EAE6DF;
10	  --fog-200:   #D9D4CB;
11	  --stone-300: #BDB7AC;
12	  --ink-700:   #55514A;
13	  --ink-900:   #25231F;
14	  --clay-700:  #8A3F22;
15	  --clay-800:  #6F3019;
16	  --clay-900:  #5A2813;
17	  --mist-300:  #B9C4C8; /* DECORATIVO apenas */
18	
19	  /* ---------- Aliases semânticos ---------- */
20	  --background-canvas:  var(--fog-50);
21	  --background-surface: var(--fog-100);
22	  --background-chip:    var(--fog-200);
23	  --background-inverse: var(--ink-900);
24	  --background-hover:   var(--fog-100);
25	  --background-pressed: var(--fog-200);
26	  --background-placeholder-mist: var(--mist-300);
27	
28	  --text-primary:           var(--ink-900);
29	  --text-secondary:         var(--ink-700);
30	  --text-link:              var(--clay-700);
31	  --text-inverse:           var(--fog-50);
32	  --text-inverse-secondary: var(--stone-300);
33	
34	  --action-primary:        var(--clay-700);
35	  --action-primary-hover:  var(--clay-800);
36	  --action-primary-active: var(--clay-900);
37	  --action-on-primary:     var(--fog-50);
38	
39	  --border-default: var(--fog-200);   /* decorativo */
40	  --border-strong:  var(--ink-700);   /* borda de placeholder; 4,43 a 7,00 sobre fog-50/100/200 e mist-300 */
41	
42	  --focus-ring:         var(--ink-900);
43	  --focus-ring-inverse: var(--fog-50);
44	
45	  --brand-mark:   var(--ink-900);
46	  --brand-accent: var(--clay-700);
47	
48	  /* ---------- Tipografia ---------- */
49	  --font-display: "Fraunces", "Iowan Old Style", "Palatino Linotype", Georgia, serif;
50	  --font-text:    "Figtree", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
51	
52	  --weight-light: 300;
53	  --weight-regular: 400;
54	  --weight-medium: 500;
55	  --weight-semibold: 600;
56	
57	  --size-xs:   0.8125rem;
58	  --size-sm:   0.875rem;
59	  --size-base: 1.0625rem;
60	  --size-lg:   clamp(1.1875rem, 1.1rem + 0.5vw, 1.375rem);
61	  --size-h3:   1.375rem;
62	  --size-h2:   clamp(1.75rem, 1.4rem + 1.8vw, 2.5rem);
63	  --size-h1:   clamp(2.25rem, 1.4rem + 3.2vw, 4rem);
64	
65	  --leading-tight:   1.1;
66	  --leading-heading: 1.2;
67	  --leading-ui:      1.4;
68	  --leading-body:    1.6;
69	
70	  --tracking-display: -0.01em;
71	  --tracking-label:   0.02em;
72	
73	  /* ---------- Espaçamento (base 4 px) ---------- */
74	  --space-1: 4px;
75	  --space-2: 8px;
76	  --space-3: 12px;
77	  --space-4: 16px;
78	  --space-5: 20px;
79	  --space-6: 24px;
80	  --space-8: 32px;
81	  --space-10: 40px;
82	  --space-12: 48px;
83	  --space-16: 64px;
84	  --space-20: 80px;
85	  --space-24: 96px;
86	  --space-32: 128px;
87	
88	  /* ---------- Layout ---------- */
89	  --gutter: clamp(1rem, 5vw, 2rem);
90	  --container: 72rem;          /* a loja (DEV-002) usa 80rem, definido em styles.css */
91	  --measure: 62ch;
92	  --header-height: 56px;
93	  --anchor-offset: 5rem;       /* use em scroll-padding-top e scroll-margin-top */
94	  --section-y: 64px;           /* mobile; 112px a partir de 1024px (ver abaixo) */
95	  --target-min: 24px;
96	  --target-comfort: 44px;
97	
98	  /* ---------- Raio ---------- */
99	  --radius-none: 0;
100	  --radius-sm: 4px;
101	  --radius-md: 10px;
102	  --radius-lg: 20px;
103	  --radius-arch: 999px 999px 10px 10px;
104	  --radius-pill: 999px;
105	
106	  /* ---------- Foco e bordas ---------- */
107	  --focus-width: 3px;
108	  --focus-offset: 3px;
109	  --focus-offset-tight: 2px;
110	  --border-hairline: 1px;
111	  --border-dashed-width: 2px;
112	
113	  /* ---------- Elevação ---------- */
114	  --elevation-none: none;
115	
116	  /* ---------- Movimento ---------- */
117	  --motion-fast: 120ms;
118	  --motion-base: 200ms;
119	  --motion-easing: cubic-bezier(0.2, 0, 0, 1);
120	  --scroll-behavior: smooth;
121	}
122	
123	@media (min-width: 1024px) {
124	  :root { --section-y: 112px; }
125	}
126	
127	/* Movimento reduzido: nenhuma transição, rolagem imediata (WCAG 2.3.3 como boa prática; AC-NAV-06) */
128	@media (prefers-reduced-motion: reduce) {
129	  :root {
130	    --motion-fast: 0s;
131	    --motion-base: 0s;
132	    --scroll-behavior: auto;
133	  }
134	}
135	
136	/* Uso esperado (referência, não obrigatório aqui):
137	   html { scroll-behavior: var(--scroll-behavior); scroll-padding-top: var(--anchor-offset); }
138	   :where([id]) { scroll-margin-top: var(--anchor-offset); }
139	   :focus-visible { outline: var(--focus-width) solid var(--focus-ring); outline-offset: var(--focus-offset); }
140	*/
